    if (id === 's2') return `<label>标注类别<select id="s2-category"><option>机场</option><option>桥梁</option><option>舰船</option><option>车辆</option><option>其他</option></select></label><label>画布缩放<input id="s2-zoom" type="range" min="0.75" max="1.5" step="0.05" value="1"><output id="s2-zoom-value">100%</output></label><p class="scenario-help">在图像空白处按住拖动创建框；点击已有框选中。框坐标和面积均来自当前画布计算。</p><button id="s2-delete" class="scenario-small-button">删除选中框</button><div class="scenario-model-note">模型推理：未配置模型权重，未运行自动检测。</div>`;
    if (id === 's3') return `<label>指数公式<select id="s3-index"><option value="NDWI">NDWI = (Green − NIR) / (Green + NIR)</option><option value="MNDWI">MNDWI = (Green − SWIR) / (Green + SWIR)</option></select></label><label>分割阈值<input id="s3-threshold" type="number" min="-1" max="1" step="0.01" value="0.20"></label><label>模拟像元尺寸（m）<input id="s3-pixel" type="number" min="1" max="1000" step="1" value="10"></label><label>Green 波段<select id="s3-green"><option value="green">Green</option><option value="nir">NIR（教学映射）</option><option value="swir1">SWIR（教学映射）</option></select></label><label>NIR 波段<select id="s3-nir"><option value="nir">NIR</option><option value="green">Green（教学映射）</option></select></label><label>SWIR 波段<select id="s3-swir"><option value="swir1">SWIR1</option><option value="green">Green（教学映射）</option></select></label>`;
    if (id === 's4') return `<label>控制点数量<input id="s4-count" type="number" min="3" max="8" step="1" value="5"></label><label>测量噪声（坐标单位）<input id="s4-noise" type="number" min="0" max="5" step="0.1" value="0.6"></label><label>目标像素 X<input id="s4-target-x" type="number" min="0" max="100" step="1" value="58"></label><label>目标像素 Y<input id="s4-target-y" type="number" min="0" max="80" step="1" value="42"></label><button id="s4-add" class="scenario-small-button">在图上添加控制点</button><button id="s4-delete" class="scenario-small-button">删除选中点</button><p class="scenario-help">前 3 个或更多控制点用于拟合；若存在独立检查点，页面会单独列出其残差。</p>`;
    if (id === 's5') return `<label>障碍密度<input id="s5-density" type="range" min="0.05" max="0.35" step="0.01" value="0.16"><output id="s5-density-value">0.16</output></label><label>代价权重<input id="s5-weight" type="range" min="0" max="4" step="0.1" value="1"><output id="s5-weight-value">1.0</output></label><label>任务访问顺序<select id="s5-order"><option value="nearest">最近邻启发式</option><option value="2opt">最近邻 + 2-opt</option></select></label><p class="scenario-help">拖动画布中的彩色任务点可改变位置。网格是抽象教学场景，不对应现实地理位置。</p>`;
    return `<label>融合算法<select id="s6-algorithm"><option value="Brovey">Brovey 变换</option><option value="IHS">IHS 强度替换</option><option value="PCA">PCA 第一主成分替换</option></select></label><p class="scenario-help">合成 PAN 为高空间分辨率单通道，MS 为低空间分辨率三波段。融合前执行最近邻上采样。</p><div class="scenario-model-note">指标参考：同一生成器保留的高分辨率 RGB 仅用于教学对照，不等同真实融合精度。</div>`;
